/* Virtual scene: metres, synthetic data, independent of geographic coordinates. */
const THREE=await import('https://unpkg.com/three@0.180.0/build/three.module.js');
const sectors=window.TWIN_SECTORS,$=s=>document.querySelector(s),host=$('#twin-canvas');
const scene=new THREE.Scene();scene.background=new THREE.Color('#030914');scene.fog=new THREE.FogExp2('#061022',.000065);
const camera=new THREE.PerspectiveCamera(48,innerWidth/innerHeight,4,22000);
const renderer=new THREE.WebGLRenderer({antialias:false,powerPreference:'high-performance'});renderer.setPixelRatio(Math.min(devicePixelRatio,1.35));renderer.setSize(innerWidth,innerHeight);host.append(renderer.domElement);
const target=new THREE.Vector3(),dummy=new THREE.Object3D(),headquarters=[],racks=[],clean=[],portals=[],streams=[];
let active=sectors[0],level=1,enabled=false,frame=0,tween=null,until=0,last=0,fpsFrames=0,fpsStart=0,selectedEquipment=sectors[0].equipment[0].id;
const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
function height(x,z){const s=sectors.reduce((a,b)=>Math.hypot(x-a.x,z-a.z)<Math.hypot(x-b.x,z-b.z)?a:b),dx=x-s.x,dz=z-s.z,r=Math.hypot(dx,dz);if(s.id==='T01')return 12;if(s.id==='T02')return -150+330*Math.exp(-Math.pow((r-1050)/360,2));if(s.id==='T03')return Math.floor(Math.max(0,Math.min(4,(dz+1500)/600)))*50;return -65+150*Math.pow(Math.min(1,r/1900),4);}
const terrainGeometry=new THREE.PlaneGeometry(10000,10000,160,160);terrainGeometry.rotateX(-Math.PI/2);const vertices=terrainGeometry.attributes.position;for(let i=0;i<vertices.count;i++)vertices.setY(i,height(vertices.getX(i),vertices.getZ(i)));terrainGeometry.computeVertexNormals();
scene.add(new THREE.Mesh(terrainGeometry,new THREE.MeshBasicMaterial({color:'#081c2c'})));const wire=new THREE.Mesh(terrainGeometry,new THREE.MeshBasicMaterial({color:'#247a87',wireframe:true,transparent:true,opacity:.22}));wire.position.y=.6;scene.add(wire);
let seed=419;function random(){seed=(seed*1664525+1013904223)>>>0;return seed/4294967296;}
const buildingGeometry=new THREE.BoxGeometry(1,1,1);const domeGeometry=new THREE.SphereGeometry(.5,12,8,0,Math.PI*2,0,Math.PI/2);
function cityMaterial(s){return new THREE.ShaderMaterial({uniforms:{body:{value:new THREE.Color(s.body)},neon:{value:new THREE.Color(s.color)}},vertexShader:`varying vec2 tex;varying vec3 norm;void main(){tex=uv;norm=normal;gl_Position=projectionMatrix*modelViewMatrix*instanceMatrix*vec4(position,1.);}`,fragmentShader:`varying vec2 tex;varying vec3 norm;uniform vec3 body;uniform vec3 neon;void main(){float windows=step(.68,fract(tex.x*6.))*step(.62,fract(tex.y*18.))*(1.-abs(norm.y));gl_FragColor=vec4(body*(.7+.3*abs(norm.z))+neon*windows*.85,1.);}`});}
sectors.forEach(s=>{
 const buildings=new THREE.InstancedMesh(s.id==='T02'?domeGeometry:buildingGeometry,cityMaterial(s),2601);for(let i=0;i<2601;i++){let x=s.x+((i%51)-25)*54,z=s.z+(Math.floor(i/51)-25)*54;if(Math.abs(x-s.x)<190&&Math.abs(z-s.z)<190){x+=320;}const h=s.id==='T01'?120+random()*380:s.id==='T02'?35+random()*50:s.id==='T03'?35+random()*65:8+random()*16;const base=s.id==='T04'?12:height(x,z);dummy.position.set(x,base+(s.id==='T02'?0:h/2),z);const width=s.id==='T01'?12+random()*7:s.id==='T02'?42:s.id==='T04'?43:24;dummy.scale.set(width,h,width);dummy.updateMatrix();buildings.setMatrixAt(i,dummy.matrix);}buildings.instanceMatrix.needsUpdate=true;buildings.computeBoundingSphere();scene.add(buildings);
 const y=s.id==='T04'?12:height(s.x,s.z);s.ground=y;const shell=new THREE.Mesh(s.id==='T02'?new THREE.SphereGeometry(105,24,12,0,Math.PI*2,0,Math.PI/2):new THREE.BoxGeometry(180,180,140),new THREE.MeshBasicMaterial({color:s.body,transparent:true,opacity:1}));shell.position.set(s.x,y+(s.id==='T02'?0:90),s.z);scene.add(shell);const outline=new THREE.LineSegments(new THREE.EdgesGeometry(shell.geometry),new THREE.LineBasicMaterial({color:s.color}));outline.position.copy(shell.position);scene.add(outline);headquarters.push(shell);
 const floor=new THREE.Mesh(new THREE.BoxGeometry(180,3,140),new THREE.MeshBasicMaterial({color:'#395169'}));floor.position.set(s.x,y+2,s.z);scene.add(floor);
 for(const [list,count,kind] of [[racks,s.equipment[0].count,'RACK'],[clean,s.equipment[1].count,'CLEAN']]){const mat=new THREE.MeshBasicMaterial({color:kind==='RACK'?'#ff9b35':'#a3ece2'}),mesh=new THREE.InstancedMesh(new THREE.BoxGeometry(kind==='RACK'?8:17,kind==='RACK'?24:17,10),mat,count);for(let i=0;i<count;i++){const cols=Math.ceil(Math.sqrt(count)),step=Math.min(14,130/cols);dummy.position.set(s.x-65+(i%cols)*step,y+16,s.z-58+Math.floor(i/cols)*step+(kind==='CLEAN'?85:0));dummy.scale.set(count>100?.45:1,1,count>100?.45:1);dummy.updateMatrix();mesh.setMatrixAt(i,dummy.matrix);}mesh.instanceMatrix.needsUpdate=true;mesh.visible=false;list.push(mesh);scene.add(mesh);}
 const portal=new THREE.Mesh(new THREE.CylinderGeometry(36,48,190,24,1,true),new THREE.ShaderMaterial({transparent:true,depthWrite:false,side:THREE.DoubleSide,uniforms:{tint:{value:new THREE.Color(s.color)}},vertexShader:`varying vec3 n;varying vec3 v;varying vec2 t;void main(){vec4 p=modelViewMatrix*vec4(position,1.);n=normalMatrix*normal;v=-p.xyz;t=uv;gl_Position=projectionMatrix*p;}`,fragmentShader:`varying vec3 n;varying vec3 v;varying vec2 t;uniform vec3 tint;void main(){float f=pow(1.-abs(dot(normalize(n),normalize(v))),2.);gl_FragColor=vec4(tint,(.06+.4*f)*(1.-t.y*.8));}`}));portal.position.set(s.x,y+280,s.z);scene.add(portal);portals.push(portal);
});
// Sector landmarks and transport infrastructure.
sectors.forEach(s=>{
 if(s.id==='T02'){for(let i=0;i<8;i++){const angle=i*Math.PI/4,x=s.x+Math.cos(angle)*330,z=s.z+Math.sin(angle)*330;const cube=new THREE.Mesh(new THREE.BoxGeometry(110,100,110),new THREE.MeshBasicMaterial({color:'#302820'}));cube.position.set(x,height(x,z)+30,z);scene.add(cube);const edges=new THREE.LineSegments(new THREE.EdgesGeometry(cube.geometry),new THREE.LineBasicMaterial({color:s.color}));edges.position.copy(cube.position);scene.add(edges);}}
 if(s.id==='T03'){for(let i=0;i<7;i++){const z=s.z-1050+i*350,bridge=new THREE.Mesh(new THREE.BoxGeometry(2200,8,24),new THREE.MeshBasicMaterial({color:s.color}));bridge.position.set(s.x,height(s.x,z)+120,z);scene.add(bridge);}}
 if(s.id==='T04'){const water=new THREE.Mesh(new THREE.PlaneGeometry(3050,3050),new THREE.MeshBasicMaterial({color:'#19234d',transparent:true,opacity:.86,side:THREE.DoubleSide}));water.rotation.x=-Math.PI/2;water.position.set(s.x,0,s.z);scene.add(water);for(let i=0;i<4;i++){const canal=new THREE.Mesh(new THREE.PlaneGeometry(150,2700),new THREE.MeshBasicMaterial({color:'#512d83',side:THREE.DoubleSide}));canal.rotation.x=-Math.PI/2;canal.position.set(s.x-1100+i*720,2,s.z);scene.add(canal);}}
});
for(let i=0;i<4;i++){const a=sectors[i],b=sectors[(i+1)%4],curve=new THREE.QuadraticBezierCurve3(new THREE.Vector3(a.x,a.ground+210,a.z),new THREE.Vector3((a.x+b.x)/2,800,(a.z+b.z)/2),new THREE.Vector3(b.x,b.ground+210,b.z));scene.add(new THREE.Line(new THREE.BufferGeometry().setFromPoints(curve.getPoints(64)),new THREE.LineBasicMaterial({color:a.color,transparent:true,opacity:.5})));const orb=new THREE.Mesh(new THREE.SphereGeometry(15,8,6),new THREE.MeshBasicMaterial({color:a.color}));scene.add(orb);streams.push({curve,orb});}
function invalidate(ms=0){until=Math.max(until,performance.now()+ms);if(enabled&&!document.hidden&&!frame)frame=requestAnimationFrame(render);}
function render(now){frame=0;if(!enabled||document.hidden)return;const moving=!!tween;if(tween){const t=Math.min(1,(now-tween.start)/tween.duration),e=t*t*(3-2*t);camera.position.lerpVectors(tween.from,tween.to,e);camera.position.y+=Math.sin(Math.PI*t)*tween.arc;target.lerpVectors(tween.targetFrom,tween.targetTo,e);if(t===1)tween=null;}camera.lookAt(target);streams.forEach((s,i)=>s.orb.position.copy(s.curve.getPoint((now/6000+i*.25)%1)));const index=sectors.indexOf(active);racks.forEach((r,i)=>r.material.color.set(i===index&&level===3&&selectedEquipment===active.equipment[0].id&&now<until?(Math.sin(now*.009)>0?'#ff9b35':'#a35119'):'#718499'));clean.forEach((r,i)=>r.material.color.set(i===index&&level===3&&selectedEquipment===active.equipment[1].id&&now<until?(Math.sin(now*.009)>0?'#ff9b35':'#a35119'):'#a3ece2'));renderer.render(scene,camera);
 fpsFrames++;if(now-fpsStart>500){$('#twin-fps').textContent=moving||now<until?Math.round(fpsFrames*1000/(now-fpsStart))+' FPS · 動':'IDLE';fpsFrames=0;fpsStart=now;}$('#twin-meter').textContent='X '+camera.position.x.toFixed(0)+' / Y '+camera.position.y.toFixed(0)+' / Z '+camera.position.z.toFixed(0)+' m · '+renderer.info.render.calls+' draws';last=now;if(tween||now<until)invalidate();else $('#twin-fps').textContent='IDLE · on-demand';}
function go(next){level=next;const i=sectors.indexOf(active),p=new THREE.Vector3(active.x,active.ground,active.z);headquarters.forEach((h,j)=>{h.material.opacity=next===3&&j===i?.1:1;h.material.wireframe=next===3&&j===i;});racks.forEach((r,j)=>r.visible=next===3&&j===i);clean.forEach((r,j)=>r.visible=next===3&&j===i);const dest=next===1?new THREE.Vector3(6100,6500,7600):next===2?p.clone().add(new THREE.Vector3(430,380,480)):p.clone().add(new THREE.Vector3(135,130,190));const to=next===1?new THREE.Vector3():p.clone().add(new THREE.Vector3(0,next===2?150:25,0));tween={from:camera.position.clone(),to:dest,targetFrom:target.clone(),targetTo:to,start:performance.now(),duration:reduced?1:next===3?1600:3000,arc:next===3?20:600};$('#twin-stage').textContent=['','L1 / MACRO WORLD','L2 / ROOFTOP','L3 / INTERIOR X-RAY'][next];renderPanels();invalidate(reduced?0:4200);}
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function renderPanels(){const s=active,a=window.twinAudit(s.required,s.actual);$('#twin-sectors').innerHTML=sectors.map(b=>'<button data-sector="'+b.id+'" aria-pressed="'+(s===b)+'" style="--sector:'+b.color+'">'+esc(b.name)+'</button>').join('');$('#twin-cards').innerHTML='<h2>'+esc(s.title)+'</h2><p>'+esc(s.company)+' · 합성 공고</p><p>'+esc(s.ecosystem)+'</p><div class="twin-metrics"><strong>'+s.budget+'억<small>사업 예산</small></strong><strong>8개월<small>과업 기간</small></strong></div><p>과업 요건을 누르면 내부 설비를 표시합니다.</p>'+s.equipment.map(e=>'<button data-equipment="'+e.id+'">↳ '+esc(e.label)+'<small>'+e.id+'</small></button>').join('');$('#twin-graph').innerHTML='<div class="tg-row"><button data-level="2">'+s.id+' 가상 공고</button><span>↔</span><button data-level="2">'+esc(s.company)+'</button></div><div class="tg-connector">↓ 문서·설비 ID 연결</div><div class="tg-row">'+s.equipment.map(e=>'<button data-equipment="'+e.id+'" class="'+(level===3&&e.id===selectedEquipment?'lit':'')+'">'+esc(e.label)+'<small>'+e.id+'</small></button>').join('')+'</div>';$('#twin-docs').innerHTML=s.docs.map((d,i)=>'<button data-twindoc="'+i+'">'+d.name+'</button>').join('');$('#twin-audit').innerHTML='<span class="eyebrow">RULE-BASED AUDIT / 합성 정답</span><p>요구 '+s.required+'억 ↔ 회사 '+s.actual+'억</p><strong class="'+(a.pass?'pass':'fail')+'">'+(a.pass?'실적 기준 충족':'실적 기준 불일치 · '+a.gap+'억 부족')+'</strong><p class="fine">단일 수치 규칙 검사입니다. 다른 자격 및 모델 정확도를 의미하지 않습니다.</p><button data-twindoc="11">RFP 제4조 · PDF 근거 열기 ↗</button>';}
function openPDF(index){const s=active,d=s.docs[index],dialog=$('#source-drawer');$('#drawer-title').textContent=d.name+' · '+d.section;$('#drawer-meta').textContent=d.id+' / 가상 문서';$('#drawer-body').innerHTML='<p><mark>'+esc(d.text)+'</mark></p><a href="twin-pdfs/'+s.id+'.pdf#page='+(index+1)+'" target="_blank" rel="noopener">PDF 새 탭으로 열기 ↗</a><iframe title="'+esc(d.name)+' 합성 원문 PDF" src="twin-pdfs/'+s.id+'.pdf#page='+(index+1)+'" style="width:100%;height:52vh;border:0;margin-top:12px"></iframe>';if(!dialog.open)dialog.showModal();}
$('#twin-world').addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.sector){active=sectors.find(s=>s.id===b.dataset.sector);selectedEquipment=active.equipment[0].id;go(2);}if(b.dataset.level)go(Number(b.dataset.level));if(b.dataset.equipment){selectedEquipment=b.dataset.equipment;go(3);}if(b.dataset.twindoc!==undefined)openPDF(Number(b.dataset.twindoc));});
const ray=new THREE.Raycaster(),pointer=new THREE.Vector2();let drag=null,dragged=false;
renderer.domElement.addEventListener('pointerdown',e=>{drag={x:e.clientX,y:e.clientY};dragged=false;renderer.domElement.setPointerCapture(e.pointerId);tween=null;});renderer.domElement.addEventListener('pointermove',e=>{if(!drag)return;const dx=e.clientX-drag.x,dy=e.clientY-drag.y;if(Math.abs(dx)+Math.abs(dy)>2)dragged=true;const offset=camera.position.clone().sub(target),sp=new THREE.Spherical().setFromVector3(offset);sp.theta-=dx*.004;sp.phi=THREE.MathUtils.clamp(sp.phi+dy*.004,.12,1.48);camera.position.copy(target).add(new THREE.Vector3().setFromSpherical(sp));drag={x:e.clientX,y:e.clientY};invalidate();});renderer.domElement.addEventListener('pointerup',e=>{drag=null;if(dragged)return;pointer.set(e.clientX/innerWidth*2-1,-e.clientY/innerHeight*2+1);ray.setFromCamera(pointer,camera);const hit=ray.intersectObjects([...headquarters,...portals])[0];if(hit){const i=headquarters.indexOf(hit.object)>=0?headquarters.indexOf(hit.object):portals.indexOf(hit.object);active=sectors[i];selectedEquipment=active.equipment[0].id;go(2);}});renderer.domElement.addEventListener('pointercancel',()=>drag=null);renderer.domElement.addEventListener('wheel',e=>{e.preventDefault();tween=null;const off=camera.position.clone().sub(target).multiplyScalar(Math.exp(e.deltaY*.001));off.clampLength(120,16000);camera.position.copy(target).add(off);invalidate();},{passive:false});
addEventListener('resize',()=>{camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight);invalidate();});document.addEventListener('visibilitychange',()=>{if(document.hidden){cancelAnimationFrame(frame);frame=0;}else invalidate();});
camera.position.set(6100,6500,7600);camera.lookAt(target);renderPanels();
window.twinScene={activate(on){enabled=on;if(on){fpsStart=performance.now();invalidate(reduced?0:2400);}else{cancelAnimationFrame(frame);frame=0;tween=null;}},go};
window.dispatchEvent(new Event('twin-ready'));
